+		...recordedEnvelope(TEST_ORIGIN),
+	});
+	ctx.recordStore.append({
+		runId: RUN,
+		stream: "budget",
+		idempotencyKey: `budget:implementation-review:${payload.id}`,
+		payload: encodeImplementationReviewObservationPayload(payload),
