+	const phases = committed.indexOf("## Phase 1");
+	writeFileSync(
+		fx.planPath,
+		committed.slice(0, phases) +
+			committed.slice(phases).replace(/^(\s*)- (?!\[)/gm, "$1- [ ] "),
+	);
+	try {
+		ok(
+			await cli(
+				fx.dir,
+				[
+					"protocol",
+					"validate",
+					"reviewer",
+					"--run",
+					sourceId,
+					"--record",
+					"--step",
+					"reviewer:plan",
+					"--phase",
+					"plan",
+					"--iteration",
+					"0",
+				],
+				PLAN_READY,
+			),
+		);
+	} finally {
+		writeFileSync(fx.planPath, committed);
+	}
+	const completed = ok(
+		await cli(fx.dir, [
+			"run",
